document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("mulch-form"),n=document.getElementById("mulch-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("mulch-length").value),a=parseFloat(document.getElementById("mulch-width").value),s=parseFloat(document.getElementById("mulch-additional").value),p=parseFloat(document.getElementById("mulch-depth").value),l=parseFloat(document.getElementById("mulch-type").value),i=document.getElementById("mulch-purchase").value;if(t<=0||a<=0||p<=0)return n.textContent="Please enter valid dimensions.",void 0;const r=t*a,d=r+s,o=d*(p/12),c=o/27,u=c+.1*c;let m,h,v,$;if("bulk"===i){m=Math.ceil(2*u)/2,h="cubic yards",$=m*l;$+=m>=3?75:100}else{const e=Math.ceil(o/2),n=Math.ceil(1.1*e);v=l/13.5,m=n,h="bags (2 cu ft each)",$=n*v}const g=c*(36/p),y=d*(1/12)/27,f=.3*d;n.innerHTML=`\n        <div class="result-section">\n          <h4>Area & Volume Calculations:</h4>\n          <p>Main bed: ${t}' × ${a}' = ${r} sq ft</p>\n          ${s>0?`<p>Additional area: ${s} sq ft</p>`:""}\n          <p><strong>Total area: ${d} sq ft</strong></p>\n          <p><strong>Mulch depth: ${p} inches</strong></p>\n          <p><strong>Volume needed: ${c.toFixed(2)} cubic yards</strong></p>\n          <p>With 10% extra: ${u.toFixed(2)} cubic yards</p>\n        </div>\n        \n        <div class="result-purchase">\n          <h4>Purchase Recommendations:</h4>\n          <p><strong>Order: ${m} ${h}</strong></p>\n          <p><strong>Estimated cost: $${$.toFixed(0)}</strong></p>\n          ${"bulk"===i?"\n          <p><em>Includes delivery fee ($75-100)</em></p>\n          <p>💡 Bulk delivery requires truck access</p>\n          ":`\n          <p><em>Bagged mulch @ ~$${v.toFixed(2)} per bag</em></p>\n          <p>💡 Can transport in standard vehicle</p>\n          `}\n        </div>\n        \n        <div class="result-coverage">\n          <h4>Coverage Information:</h4>\n          <p>At ${p}" depth: covers ${d} sq ft</p>\n          <p>At 3" depth: would cover ${g.toFixed(0)} sq ft</p>\n          <p>Weight estimate: ${(1e3*u).toFixed(0)} lbs</p>\n          <p>Truck loads: ${Math.ceil(u/10)} (10 yard truck)</p>\n        </div>\n        \n        <div class="result-maintenance">\n          <h4>Annual Maintenance:</h4>\n          <p>Yearly refresh: ${y.toFixed(2)} cubic yards</p>\n          <p>Refresh cost: $${(y*l).toFixed(0)} annually</p>\n          <p>Complete replacement: every 2-3 years</p>\n        </div>\n        \n        <div class="result-benefits">\n          <h4>Environmental Benefits:</h4>\n          <p>💧 Water savings: ~${f.toFixed(0)} gallons/year</p>\n          <p>🌡️ Soil temperature moderation</p>\n          <p>🌱 Reduced weed growth (up to 90%)</p>\n          <p>🏠 Enhanced curb appeal and property value</p>\n        </div>\n        \n        <div class="result-application">\n          <h4>Application Tips:</h4>\n          <p>📏 Keep 3-6" away from plant stems</p>\n          <p>🌿 Apply after soil warms in spring</p>\n          <p>🔧 Use rake to spread evenly</p>\n          <p>💡 Edge beds before applying mulch</p>\n        </div>\n        \n        <div class="result-comparison">\n          <h4>Cost Comparison:</h4>\n          ${"bulk"===i?`\n          <p>Bulk: $${$.toFixed(0)} (${m} yards)</p>\n          <p>Bagged equivalent: $${(Math.ceil(o/2)*v*1.5).toFixed(0)} (${Math.ceil(o/2)} bags)</p>\n          <p>💰 Bulk saves: $${(Math.ceil(o/2)*v*1.5-$).toFixed(0)}</p>\n          `:`\n          <p>Bagged: $${$.toFixed(0)} (${m} bags)</p>\n          <p>Bulk equivalent: $${(c*l+75).toFixed(0)} (${c.toFixed(1)} yards)</p>\n          <p>💰 Bulk saves: $${($-(c*l+75)).toFixed(0)}</p>\n          `}\n        </div>\n        \n        <div class="result-tips">\n          <p><em>🚛 Bulk delivery is most economical for areas over 5 cubic yards</em></p>\n          <p><em>🏪 Bagged mulch offers convenience for smaller projects</em></p>\n          <p><em>📅 Order in early spring for best selection and pricing</em></p>\n        </div>\n      `})});